// Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
}

public List<Integer> inorderTraversal(TreeNode root) {
    List<Integer> out = new ArrayList<>();
    inorder(root, out);
    return out;
}

private void inorder(TreeNode node, List<Integer> out) {
    if (node == null) return;        // base case
    inorder(node.left, out);          // left
    out.add(node.val);                // node
    inorder(node.right, out);         // right
}

// Preorder: move out.add(node.val) ABOVE inorder(node.left, ...)
// Postorder: move out.add(node.val) BELOW inorder(node.right, ...)

public List<Integer> inorderTraversal(TreeNode root) {
    List<Integer> out = new ArrayList<>();
    Deque<TreeNode> stack = new ArrayDeque<>();
    TreeNode curr = root;
    while (curr != null || !stack.isEmpty()) {
        while (curr != null) {        // dive to the leftmost node
            stack.push(curr);
            curr = curr.left;
        }
        curr = stack.pop();           // leftmost unvisited node
        out.add(curr.val);            // visit it
        curr = curr.right;            // then explore its right subtree
    }
    return out;
}

